import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { Download, Eye, FileText, Pencil, Plus, RefreshCw, Search, SlidersHorizontal, Trash2, Upload, X } from 'lucide-react';
import { SystemModal } from './SystemModal';
import { designerRequestService, formatCreatorLabel, validateReferenceFile, type CreateDesignerRequest, type DesignType, type DesignerReferenceAttachment, type DesignerRequestCreator, type DesignerRequestV2, type DesignerStage, type StageStatus, type TaskType, type WorkMode } from '../services/designer-request.service';
import { canRemoveDesignerReference, designerReferenceUploadsEnabled } from '../services/designer-reference-feature';
import { ReferenceStorageCleanupError } from '../services/designer-reference-upload';
import { useAuth } from '../hooks/useAuth';

type Tab = 'design' | 'setup';
type DesignerMode = 'intake' | 'progress';
type DesignerWorkstream = 'creative' | 'setup';
type StageAction = 'claim' | 'arrange' | 'start' | 'submit';
type WorkflowItem = DesignerRequestV2 & { stage?: DesignerStage };
type RequestForm = CreateDesignerRequest;
type PendingReference = { file: File; scope: 'shared' | 'items'; itemIds: string[] };
type AgentStatusFilter = 'all' | 'processing' | 'awaiting' | 'completed' | 'cancelled';

type AgentFilters = { keyword: string; taskType: string; workMode: string; status: AgentStatusFilter; applicationDate: string };
type IntakeFilters = { keyword: string; taskType: string; designType: string; applicant: string; eventDate: string; submittedDate: string; region: string };
type ProgressFilters = { owner: string; stageType: string; status: string; keyword: string; applicant: string; eventDate: string; activeOnly: boolean };

const emptyForm: RequestForm = { creatorProfileId: '', workMode: 'design_only', taskType: 'daily', requestType: 'banner', otherDesignType: '', eventStartAt: '', eventEndAt: '', content: '', style: '', color: '', specification: '', specialContent: '', referenceMaterialStatus: 'not_required', liveRoom: '' };
const stageNames: Record<string, string> = { design: '设计', production: '制作', setup: '布置', unclaimed: '待接单', scheduled: '待安排', arranged: '已安排', in_progress: '进行中', awaiting_agent_confirmation: '待申请人确认', revision: '问题处理中', completed: '已完成' };
const taskTypeNames: Record<TaskType, string> = { daily: '日常', activity: '活动' };
const designTypeNames: Record<DesignType, string> = { poster: '海报', banner: 'Banner', standee: '立牌', special: '其他' };
const emptyAgentFilters: AgentFilters = { keyword: '', taskType: '', workMode: '', status: 'processing', applicationDate: '' };
const emptyIntakeFilters: IntakeFilters = { keyword: '', taskType: '', designType: '', applicant: '', eventDate: '', submittedDate: '', region: '' };
const emptyProgressFilters: ProgressFilters = { owner: '', stageType: '', status: '', keyword: '', applicant: '', eventDate: '', activeOnly: false };
const initialProgressFilters: ProgressFilters = { ...emptyProgressFilters, activeOnly: true };

function displayStageStatus(stage: DesignerStage): string {
  if (stage.stage_type === 'design' && stage.status === 'in_progress') return '设计中';
  if (stage.stage_type === 'production' && stage.status === 'in_progress') return '制作中';
  if (stage.stage_type === 'setup' && stage.status === 'in_progress') return '布置中';
  if (stage.stage_type === 'production' && stage.status === 'awaiting_agent_confirmation') return '待申请人最终确认';
  return stageNames[stage.status] ?? stage.status;
}

export function AgentDesignerRequests() {
  const [items, setItems] = useState<DesignerRequestV2[]>([]);
  const [creators, setCreators] = useState<DesignerRequestCreator[]>([]);
  const [tab, setTab] = useState<Tab>('design');
  const [form, setForm] = useState<RequestForm | null>(null); const [editing, setEditing] = useState<DesignerRequestV2 | null>(null); const [cancelling, setCancelling] = useState<DesignerRequestV2 | null>(null);
  const [detail, setDetail] = useState<DesignerRequestV2 | null>(null);
  const [requestsError, setRequestsError] = useState('');
  const [creatorsError, setCreatorsError] = useState('');
  const [actionError, setActionError] = useState('');
  const [requestsLoading, setRequestsLoading] = useState(true);
  const [creatorsLoading, setCreatorsLoading] = useState(true);
  const [filters, setFilters] = useState<AgentFilters>(emptyAgentFilters);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const load = useCallback(async () => {
    setRequestsLoading(true); setCreatorsLoading(true); setRequestsError(''); setCreatorsError('');
    await Promise.all([
      designerRequestService.listAgentRequests().then(setItems).catch((reason: unknown) => setRequestsError(errorMessage(reason))).finally(() => setRequestsLoading(false)),
      designerRequestService.listEligibleCreators().then(setCreators).catch((reason: unknown) => setCreatorsError(errorMessage(reason))).finally(() => setCreatorsLoading(false)),
    ]);
  }, []);
  useEffect(() => { void load(); }, [load]);
  const agentBase = useMemo(() => items
    .filter((request) => (tab === 'setup' ? request.work_mode === 'setup_only' : request.work_mode !== 'setup_only'))
    .filter((request) => matchesKeyword(request, filters.keyword))
    .filter((request) => !filters.taskType || request.task_type === filters.taskType)
    .filter((request) => !filters.workMode || request.work_mode === filters.workMode)
    .filter((request) => !filters.applicationDate || malaysiaDateKey(request.created_at) === filters.applicationDate), [items, tab, filters.keyword, filters.taskType, filters.workMode, filters.applicationDate]);
  const counts = useMemo(() => agentBase.reduce((result, item) => ({ ...result, [agentBucket(item)]: result[agentBucket(item)] + 1 }), { all: agentBase.length, processing: 0, awaiting: 0, completed: 0, cancelled: 0 }), [agentBase]);
  const visible = useMemo(() => agentBase.filter((request) => filters.status === 'all' || agentBucket(request) === filters.status).sort(sortAgentRequests), [agentBase, filters.status]);
  async function submit(event: FormEvent<HTMLFormElement>, files: PendingReference[], note: string) { event.preventDefault(); if (!form) return; if(files.some((file)=>file.scope==='items'&&!file.itemIds.length)){setActionError('指定项目参考资料至少需要选择一个项目。');return;} setActionError(''); try { const requestId=editing?.id ?? await designerRequestService.create(form); if(editing) await designerRequestService.update(requestId, form); if(designerReferenceUploadsEnabled){await designerRequestService.updateReferenceNote(requestId,note);for(const reference of files) await designerRequestService.uploadReference(requestId,reference.file,reference.scope,reference.itemIds);} setForm(null); setEditing(null); await load(); } catch (reason) { setActionError(errorMessage(reason)); } }
  function edit(request: DesignerRequestV2) { setEditing(request); setForm({ creatorProfileId: request.creator_profile_id ?? '', workMode: request.work_mode ?? 'design_only', taskType: request.task_type ?? 'daily', requestType: request.request_type, otherDesignType: request.other_design_type ?? '', eventStartAt: dateInput(request.event_start_at), eventEndAt: dateInput(request.event_end_at), content: request.design_content ?? '', specialContent: request.special_content ?? '', style: request.style ?? '', color: request.color ?? '', specification: request.specification ?? '', referenceMaterialStatus: request.reference_material_status, liveRoom: request.live_room ?? '' }); }
  async function cancel() { if (!cancelling) return; setActionError(''); try { await designerRequestService.cancel(cancelling.id); setCancelling(null); setDetail(null); await load(); } catch (reason) { setActionError(errorMessage(reason)); } }
  async function review(stage: DesignerStage, accepted: boolean) { setActionError(''); try { if (accepted) await designerRequestService.confirm(stage.id); else { const note = window.prompt('请填写问题说明'); if (!note?.trim()) return; await designerRequestService.returnStage(stage.id, note); } setDetail(null); await load(); } catch (reason) { setActionError(errorMessage(reason)); } }
  return <section className="designer-request-page">
    <header className="designer-request-hero designer-request-agent-hero">
      <div className="designer-request-guides" aria-label="美工申请说明与价格规则">
        <section className="designer-request-guide"><strong>Banner 制作</strong><b>RM30 / 次</b><div className="designer-request-guide-details"><span>默认尺寸：100cm × 30cm</span></div><div className="designer-request-guide-rules"><div className="designer-request-guide-rule designer-request-guide-time"><span>时间</span><small>制作周期：10–15天，请提前安排</small></div><div className="designer-request-guide-rule designer-request-guide-online"><span>线上主播</span><small>月流水每达 <em>200K</em>，可申请 <em>1次 Banner 制作</em></small></div><div className="designer-request-guide-rule designer-request-guide-offline"><span>线下主播</span><small>可使用直播间累积金额抵扣</small></div></div></section>
        <section className="designer-request-guide"><strong>立牌制作</strong><b>RM50 / 次</b><div className="designer-request-guide-details" /><div className="designer-request-guide-rules"><div className="designer-request-guide-rule designer-request-guide-time"><span>时间</span><small>制作周期：10–15天，请提前安排</small></div><div className="designer-request-guide-rule designer-request-guide-offline"><span>线下主播</span><small>可使用直播间累积金额抵扣</small></div></div></section>
        <section className="designer-request-guide"><strong>活动设计与布置</strong><b>RM50 / 次</b><div className="designer-request-guide-details"><span>含基础直播间背景布置及道具搭配</span><span>额外需求将另行评估与报价</span></div><div className="designer-request-guide-rules"><div className="designer-request-guide-rule designer-request-guide-time"><span>时间</span><small>所有活动海报及布置需求须至少提前10天申请</small></div><div className="designer-request-guide-rule designer-request-guide-rule-detail"><small>逾期申请无法保证按时完成</small></div><div className="designer-request-guide-rule designer-request-guide-offline"><span>线下主播</span><small>可使用直播间累积金额抵扣</small></div></div></section>
      </div>
      <button className="designer-request-primary" type="button" onClick={() => setForm({ ...emptyForm, workMode: tab === 'setup' ? 'setup_only' : 'design_only' })}><Plus size={17} />新增申请</button>
    </header>
    <div className="designer-request-workbench">
      <div className="designer-request-workbench-header designer-request-agent-workbench-header">
        <div className="designer-request-tabs" role="tablist"><button type="button" className={tab === 'design' ? 'is-active' : ''} onClick={() => setTab('design')}>设计 / 制作</button><button type="button" className={tab === 'setup' ? 'is-active' : ''} onClick={() => setTab('setup')}>布置</button></div>
        <button className="designer-request-secondary designer-request-refresh" type="button" onClick={() => void load()}><RefreshCw size={16} />刷新</button>
      </div>
      <div className="designer-request-summary" aria-label="申请统计">{([['all', '全部'], ['processing', '处理中'], ['awaiting', '待我确认'], ['completed', '已完成'], ['cancelled', '已取消']] as const).map(([value, label]) => <button key={value} type="button" className={`designer-request-summary-card${value === 'awaiting' ? ' is-attention' : ''}${filters.status === value ? ' is-selected' : ''}`} onClick={() => setFilters((current) => ({ ...current, status: value }))}><span>{label}</span><strong>{counts[value]}</strong></button>)}</div>
      <button type="button" className="designer-request-filter-toggle" onClick={() => setFiltersOpen((open) => !open)}><SlidersHorizontal size={16} />筛选</button>
      <RequestFilters className={filtersOpen ? 'is-open' : ''}><label className="designer-request-search"><Search size={16} /><input type="search" placeholder="搜索主播名 / TikTok ID / 平台账号" value={filters.keyword} onChange={(event) => setFilters({ ...filters, keyword: event.target.value })} /></label><SelectFilter label="任务类型" value={filters.taskType} onChange={(taskType) => setFilters({ ...filters, taskType })} options={[['daily', '日常'], ['activity', '活动']]} /><SelectFilter label="工作方式" value={filters.workMode} onChange={(workMode) => setFilters({ ...filters, workMode })} options={[['design_only', '纯设计'], ['design_production', '设计 + 制作'], ['setup_only', '活动布置']]} /><SelectFilter label="状态" value={filters.status} onChange={(status) => setFilters({ ...filters, status: status as AgentStatusFilter })} options={[['all', '全部'], ['processing', '处理中'], ['awaiting', '待我确认'], ['completed', '已完成'], ['cancelled', '已取消']]} /><label className="designer-request-filter-field"><span>申请日期</span><input type="date" value={filters.applicationDate} onChange={(event) => setFilters({ ...filters, applicationDate: event.target.value })} /></label><button className="designer-request-reset" type="button" onClick={() => setFilters(emptyAgentFilters)}>重置</button></RequestFilters>
      {requestsError ? <p className="designer-request-read-error">申请列表读取失败：{requestsError}</p> : null}{actionError ? <p className="designer-request-read-error">操作失败：{actionError}</p> : null}{requestsLoading ? <div className="designer-request-empty">正在读取申请…</div> : <RequestTable items={visible} onDetail={setDetail} onEdit={edit} onCancel={setCancelling} agent hideDesignType={tab === 'setup'} />}
    </div>
    {form ? <RequestFormModal form={form} creators={creators} creatorsLoading={creatorsLoading} creatorsError={creatorsError} editing={editing} onChange={setForm} onClose={() => { setForm(null); setEditing(null); }} onSubmit={submit} /> : null}{detail ? <RequestDetail request={detail} applicant onClose={() => setDetail(null)} onReview={review} /> : null}{cancelling ? <CancelModal onClose={() => setCancelling(null)} onConfirm={cancel} /> : null}
  </section>;
}

export function DesignerWorkflow({ mode }: { mode: DesignerMode }) {
  const { profile } = useAuth(); const [items, setItems] = useState<WorkflowItem[]>([]); const [detail, setDetail] = useState<WorkflowItem | null>(null); const [error, setError] = useState(''); const [workstream, setWorkstream] = useState<DesignerWorkstream>('creative'); const [filtersOpen, setFiltersOpen] = useState(false); const [intakeFilters, setIntakeFilters] = useState<IntakeFilters>(emptyIntakeFilters); const [progressFilters, setProgressFilters] = useState<ProgressFilters>(initialProgressFilters);
  const load = useCallback(async () => { try { const next = mode === 'intake' ? await designerRequestService.listAvailableStages() : profile?.id ? await designerRequestService.listMyStages(profile.id) : []; setItems(next); } catch (reason) { setError(errorMessage(reason)); } }, [mode, profile?.id]);
  useEffect(() => { void load(); }, [load]);
  async function act(stage: DesignerStage, action: StageAction) { try { if (action === 'claim') await designerRequestService.claim(stage.id); else if (action === 'arrange' || action === 'start') await designerRequestService.advance(stage.id, action); else await designerRequestService.submit(stage.id); setDetail(null); await load(); } catch (reason) { setError(errorMessage(reason)); } }
  const regions = useMemo(() => Array.from(new Set(items.map((item) => item.region?.name).filter((value): value is string => Boolean(value)))).sort(), [items]);
  const applicants = useMemo(() => Array.from(new Set(items.map((item) => displayEmployee(item.applicant, '')).filter(Boolean))).sort(), [items]);
  const visible = useMemo(() => items.filter((item) => workstream === 'setup' ? item.stage?.stage_type === 'setup' && item.work_mode === 'setup_only' : (item.stage?.stage_type === 'design' || item.stage?.stage_type === 'production') && item.work_mode !== 'setup_only').filter((item) => mode === 'intake' ? matchesIntake(item, intakeFilters, workstream) : matchesProgress(item, progressFilters)).sort(mode === 'intake' ? (first, second) => sortIntakeRequests(first, second, workstream) : sortProgressRequests), [items, workstream, mode, intakeFilters, progressFilters]);
  return <section className="designer-request-page"><header className="designer-request-hero"><div><span>DY GROUP · CREATIVE DESK</span><h2>{mode === 'intake' ? '接单中心' : '我的工作进度'}</h2><p>{mode === 'intake' ? '选择设计 / 制作或活动布置工作区接单。' : '按工作区继续完成已接任务。'}</p></div></header><div className="designer-request-workbench"><div className="designer-request-workbench-header"><div className="designer-request-tabs" role="tablist"><button className={workstream === 'creative' ? 'is-active' : ''} type="button" onClick={() => setWorkstream('creative')}>设计 / 制作</button><button className={workstream === 'setup' ? 'is-active' : ''} type="button" onClick={() => setWorkstream('setup')}>活动布置</button></div><button className="designer-request-secondary designer-request-refresh" type="button" onClick={() => void load()}><RefreshCw size={16} />刷新</button></div>{workstream === 'setup' ? <p className="designer-request-setup-note"><strong>布置费用：RM50/次</strong>，包含基础直播间背景布置和道具搭配；额外需求另评估报价。至少提前 10 天申请，少于 10 天无法保证按时完成。</p> : null}{mode === 'progress' ? <button type="button" className={`designer-request-quick-filter${progressFilters.activeOnly ? ' is-selected' : ''}`} onClick={() => setProgressFilters({ ...emptyProgressFilters, activeOnly: true })}>我的进行中任务</button> : null}<button type="button" className="designer-request-filter-toggle" onClick={() => setFiltersOpen((open) => !open)}><SlidersHorizontal size={16} />筛选</button>{mode === 'intake' ? <RequestFilters className={filtersOpen ? 'is-open' : ''}><label className="designer-request-search"><Search size={16} /><input type="search" placeholder="搜索主播名 / TikTok ID / 平台账号" value={intakeFilters.keyword} onChange={(event) => setIntakeFilters({ ...intakeFilters, keyword: event.target.value })} /></label><SelectFilter label="任务类型" value={intakeFilters.taskType} onChange={(taskType) => setIntakeFilters({ ...intakeFilters, taskType })} options={[['daily', '日常'], ['activity', '活动']]} />{workstream === 'creative' ? <SelectFilter label="设计类型" value={intakeFilters.designType} onChange={(designType) => setIntakeFilters({ ...intakeFilters, designType })} options={Object.entries(designTypeNames)} /> : null}<SelectFilter label="申请人" value={intakeFilters.applicant} onChange={(applicant) => setIntakeFilters({ ...intakeFilters, applicant })} options={applicants.map((value) => [value, value])} /><DateFilter label="活动日期" value={intakeFilters.eventDate} onChange={(eventDate) => setIntakeFilters({ ...intakeFilters, eventDate })} /><DateFilter label="提交日期" value={intakeFilters.submittedDate} onChange={(submittedDate) => setIntakeFilters({ ...intakeFilters, submittedDate })} /><SelectFilter label="区域" value={intakeFilters.region} onChange={(region) => setIntakeFilters({ ...intakeFilters, region })} options={regions.map((value) => [value, value])} /><button className="designer-request-reset" type="button" onClick={() => setIntakeFilters(emptyIntakeFilters)}>重置</button></RequestFilters> : <RequestFilters className={filtersOpen ? 'is-open' : ''}><label className="designer-request-filter-field"><span>负责人</span><input placeholder="搜索负责人" value={progressFilters.owner} onChange={(event) => setProgressFilters({ ...progressFilters, owner: event.target.value, activeOnly: false })} /></label><SelectFilter label="当前阶段" value={progressFilters.stageType} onChange={(stageType) => setProgressFilters({ ...progressFilters, stageType, activeOnly: false })} options={[['design', '设计'], ['production', '制作'], ['setup', '布置']]} /><SelectFilter label="状态" value={progressFilters.status} onChange={(status) => setProgressFilters({ ...progressFilters, status, activeOnly: false })} options={[['scheduled', '待安排'], ['arranged', '已安排'], ['in_progress', '进行中'], ['awaiting_agent_confirmation', '待申请人确认'], ['revision', '问题处理中']]} /><label className="designer-request-search"><Search size={16} /><input type="search" placeholder="搜索主播名 / TikTok ID / 平台账号" value={progressFilters.keyword} onChange={(event) => setProgressFilters({ ...progressFilters, keyword: event.target.value, activeOnly: false })} /></label><SelectFilter label="申请人" value={progressFilters.applicant} onChange={(applicant) => setProgressFilters({ ...progressFilters, applicant, activeOnly: false })} options={applicants.map((value) => [value, value])} /><DateFilter label="活动日期" value={progressFilters.eventDate} onChange={(eventDate) => setProgressFilters({ ...progressFilters, eventDate, activeOnly: false })} /><button className="designer-request-reset" type="button" onClick={() => setProgressFilters(emptyProgressFilters)}>重置</button></RequestFilters>}{error ? <p className="form-alert">{error}</p> : null}<RequestTable items={visible} onDetail={setDetail} intake={mode === 'intake'} progress={mode === 'progress'} hideDesignType={workstream === 'setup'} /></div>{detail ? <RequestDetail request={detail} stage={detail.stage} intake={mode === 'intake'} onClose={() => setDetail(null)} onStageAction={act} /> : null}</section>;
}

function RequestTable({ items, onDetail, onEdit, onCancel, agent = false, intake = false, progress = false, hideDesignType = false }: { items: WorkflowItem[]; onDetail: (request: WorkflowItem) => void; onEdit?: (request: DesignerRequestV2) => void; onCancel?: (request: DesignerRequestV2) => void; agent?: boolean; intake?: boolean; progress?: boolean; hideDesignType?: boolean }) { return <div className="designer-request-list">{items.length === 0 ? <div className="designer-request-empty">暂无符合条件的美工申请。</div> : <><div className="designer-request-table-wrap"><table className={`designer-request-table${hideDesignType ? ' designer-request-table-setup' : ''}`}><thead><tr>{progress ? <th>当前阶段</th> : null}<th>任务类型</th><th>工作方式</th>{!hideDesignType ? <th>设计类型</th> : null}<th>主播</th><th>{agent ? '活动日期' : '申请人'}</th><th>状态</th><th>操作</th></tr></thead><tbody>{items.map((request) => { const stage = request.stage; const eligible = request.status === 'unclaimed' && request.stages.every((item) => !item.assignee_profile_id && !item.accepted_at && (item.status === 'unclaimed' || item.status === 'scheduled')); const risk = requestRisk(request); return <tr key={`${request.id}-${stage?.id ?? 'request'}`}>{progress ? <td>{stageNames[stage?.stage_type ?? '']}</td> : null}<td>{displayTaskType(request.task_type)}</td><td>{workModeLabel(request.work_mode)}</td>{!hideDesignType ? <td>{displayDesignType(request)}</td> : null}<td>{request.creator_name || '-'}</td><td>{agent ? formatDate(request.event_start_at) : displayEmployee(request.applicant, '-')} {risk ? <RiskBadge label={risk} /> : null}</td><td><StatusBadge value={stage ? displayStageStatus(stage) : request.status === 'cancelled' ? '已取消' : request.stages.map(displayStageStatus).join(' / ')} /></td><td><div className="designer-request-row-actions"><button className="designer-request-icon" type="button" onClick={() => onDetail(request)} aria-label="查看"><Eye size={16} /></button>{agent && eligible ? <><button className="designer-request-text-action" type="button" onClick={() => onEdit?.(request)}><Pencil size={14} />修改</button><button className="designer-request-danger-action" type="button" onClick={() => onCancel?.(request)}><X size={14} />取消</button></> : null}{intake ? <button className="designer-request-text-action" type="button" onClick={() => onDetail(request)}>接单</button> : null}{progress && stage ? <span className="designer-request-next">{actionLabel(nextAction(stage.status, false))}</span> : null}</div></td></tr>; })}</tbody></table></div><div className="designer-request-cards">{items.map((request) => { const risk = requestRisk(request); return <article className="designer-request-card" key={`${request.id}-${request.stage?.id ?? 'card'}`}><div><small>{progress ? `当前阶段：${stageNames[request.stage?.stage_type ?? '']}` : displayTaskType(request.task_type)}</small><h3>{request.creator_name || '-'}</h3><p>{workModeLabel(request.work_mode)}{request.work_mode !== 'setup_only' ? ` · ${displayDesignType(request)}` : ''}</p></div><StatusBadge value={request.stage ? displayStageStatus(request.stage) : request.status === 'cancelled' ? '已取消' : request.stages.map(displayStageStatus).join(' / ')} /><p>{agent ? `活动日期：${formatDate(request.event_start_at)}` : `申请人：${displayEmployee(request.applicant, '-')}`}</p>{risk ? <RiskBadge label={risk} /> : null}<button className="designer-request-text-action" type="button" onClick={() => onDetail(request)}>查看</button></article>; })}</div></>}</div>; }

function RequestFilters({ className, children }: { className: string; children: ReactNode }) { return <div className={`designer-request-filters ${className}`}>{children}</div>; }
function SelectFilter({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: readonly (readonly [string, string])[] }) { return <label className="designer-request-filter-field"><span>{label}</span><select value={value} onChange={(event) => onChange(event.target.value)}><option value="">全部</option>{options.map(([optionValue, optionLabel]) => <option key={optionValue} value={optionValue}>{optionLabel}</option>)}</select></label>; }
function DateFilter({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) { return <label className="designer-request-filter-field"><span>{label}</span><input type="date" value={value} onChange={(event) => onChange(event.target.value)} /></label>; }
function RiskBadge({ label }: { label: string }) { return <span className={`designer-request-risk${label === '已过活动日期' ? ' is-overdue' : ''}`}>{label}</span>; }

function RequestFormModal({ form, creators, creatorsLoading, creatorsError, editing, onChange, onClose, onSubmit }: { form: RequestForm; creators: DesignerRequestCreator[]; creatorsLoading: boolean; creatorsError: string; editing: DesignerRequestV2 | null; onChange: (form: RequestForm) => void; onClose: () => void; onSubmit: (event: FormEvent<HTMLFormElement>, files: PendingReference[], note: string) => void }) { const creator = creators.find((item) => item.id === form.creatorProfileId); const setup = form.workMode === 'setup_only'; const [files,setFiles]=useState<PendingReference[]>([]); const [note,setNote]=useState(editing?.reference_note ?? ''); const addFiles=(incoming:FileList|File[])=>{const next:PendingReference[]=[];for(const file of Array.from(incoming)){try{validateReferenceFile(file);if(!files.some((current)=>current.file.name===file.name&&current.file.size===file.size))next.push({file,scope:'shared',itemIds:[]});}catch(reason){window.alert(errorMessage(reason));}}setFiles((current)=>[...current,...next]);}; return <SystemModal title={editing ? '修改申请' : setup ? '新增布置申请' : '新增设计 / 制作申请'} className="designer-request-modal" onClose={onClose} footer={<><button className="designer-request-secondary" type="button" onClick={onClose}>返回</button><button className="designer-request-primary" type="submit" form="designer-request-form">{editing ? '保存修改' : '提交申请'}</button></>}><form id="designer-request-form" className="designer-request-form" onSubmit={(event)=>onSubmit(event,files,note)}><fieldset className="designer-request-section"><legend>主播资料</legend>{creatorsError ? <p className="designer-request-read-error">主播列表读取失败：{creatorsError}</p> : null}<div className="designer-request-form-grid"><Field label="主播"><select required disabled={Boolean(editing) || creatorsLoading || Boolean(creatorsError)} value={form.creatorProfileId} onChange={(event) => onChange({ ...form, creatorProfileId: event.target.value })}><option value="">{creatorsLoading ? '正在读取授权主播…' : creatorsError ? '主播列表读取失败' : '请选择授权区域内主播'}</option>{creators.map((item) => <option value={item.id} key={item.id}>{formatCreatorLabel(item)}</option>)}</select></Field><Field label="TikTok 名字 / ID"><input readOnly value={creator ? `${creator.creator_name} / ${creator.platform_user_id}` : editing ? `${editing.creator_name || '-'} / ${editing.platform_user_id || '-'}` : '选择主播后自动带入'} /></Field></div></fieldset><fieldset className="designer-request-section"><legend>任务资料</legend><div className="designer-request-form-grid"><Field label="工作方式"><select disabled={Boolean(editing)} value={form.workMode} onChange={(event) => onChange({ ...form, workMode: event.target.value as WorkMode })}><option value="design_only">纯设计</option><option value="design_production">设计 + 制作</option><option value="setup_only">布置</option></select></Field><Field label="任务类型"><select required value={form.taskType} onChange={(event) => onChange({ ...form, taskType: event.target.value as TaskType })}><option value="daily">日常</option><option value="activity">活动</option></select></Field>{!setup ? <Field label="设计类型"><select required value={form.requestType} onChange={(event) => { const requestType = event.target.value as DesignType; onChange({ ...form, requestType, otherDesignType: requestType === 'special' ? form.otherDesignType : '' }); }}><option value="poster">海报</option><option value="banner">Banner</option><option value="standee">立牌</option><option value="special">其他</option></select></Field> : null}{!setup && form.requestType === 'special' ? <TextField label="其他设计类型" value={form.otherDesignType} onChange={(otherDesignType) => onChange({ ...form, otherDesignType })} required /> : null}<Field label="活动开始"><input type="datetime-local" value={form.eventStartAt} onChange={(event) => onChange({ ...form, eventStartAt: event.target.value })} /></Field><Field label="活动结束"><input type="datetime-local" value={form.eventEndAt} onChange={(event) => onChange({ ...form, eventEndAt: event.target.value })} /></Field>{setup ? <TextField label="直播间" value={form.liveRoom} onChange={(liveRoom) => onChange({ ...form, liveRoom })} /> : null}</div></fieldset><fieldset className="designer-request-section"><legend>需求资料</legend><div className="designer-request-form-grid"><TextField label="内容" value={form.content} onChange={(content) => onChange({ ...form, content })} /><TextField label="特殊说明" value={form.specialContent} onChange={(specialContent) => onChange({ ...form, specialContent })} /><TextField label="风格 / 主题" value={form.style} onChange={(style) => onChange({ ...form, style })} /><TextField label="颜色" value={form.color} onChange={(color) => onChange({ ...form, color })} /><TextField label="款式 / 规格 / 备注" value={form.specification} onChange={(specification) => onChange({ ...form, specification })} /></div></fieldset>{designerReferenceUploadsEnabled?<fieldset className="designer-request-section"><legend>参考资料</legend><ReferenceUpload files={files} items={editing?.request_items ?? []} attachments={editing?.reference_attachments ?? []} note={note} onNote={setNote} onAdd={addFiles} onChangeFile={(file)=>setFiles((current)=>current.map((item)=>item.file===file.file?file:item))} onRemove={(file)=>setFiles((current)=>current.filter((item)=>item!==file))} /></fieldset>:null}</form></SystemModal>; }

function ReferenceUpload({files,items,attachments,note,onNote,onAdd,onChangeFile,onRemove,readonly=false,onDeleteAttachment,removingAttachmentId}:{files:PendingReference[];items:{id:string;item_type:string;item_name:string|null}[];attachments:DesignerReferenceAttachment[];note:string;onNote:(value:string)=>void;onAdd:(files:FileList|File[])=>void;onChangeFile:(file:PendingReference)=>void;onRemove:(file:PendingReference)=>void;readonly?:boolean;onDeleteAttachment?:(file:DesignerReferenceAttachment)=>void;removingAttachmentId?:string}){
  const [dragging,setDragging]=useState(false); const [urls,setUrls]=useState<Record<string,string>>({});
  const open=async(path:string)=>{try{const url=await designerRequestService.getReferenceSignedUrl(path,60);setUrls((current)=>({...current,[path]:url}));window.open(url,'_blank','noopener,noreferrer');}catch(reason){window.alert(`无法读取参考资料：${errorMessage(reason)}`);}};
  return <div className="designer-reference-upload">
    {!readonly?<label className={`designer-reference-dropzone${dragging?' is-dragging':''}`} onDragOver={(event)=>{event.preventDefault();setDragging(true);}} onDragLeave={()=>setDragging(false)} onDrop={(event)=>{event.preventDefault();setDragging(false);onAdd(event.dataTransfer.files);}}><span className="designer-reference-upload-icon"><Upload size={24}/></span><strong>参考图片 / 附件</strong><span>支持 JPG/JPEG/PNG/WebP：10MB；PDF：30MB</span><span className="designer-reference-choose">选择图片 / PDF</span><input className="sr-only" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf,.jpg,.jpeg,.png,.webp,.pdf" onChange={(event)=>{onAdd(event.target.files??[]);event.currentTarget.value='';}}/></label>:null}
    <div className="designer-reference-list">{!readonly?files.map((entry)=><div className="designer-reference-row" key={`${entry.file.name}-${entry.file.size}`}><ReferenceFileVisual file={entry.file}/><span><b>{entry.file.name}</b><small>{formatFileSize(entry.file.size)} · 等待上传</small>{items.length?<select value={entry.scope} onChange={(event)=>onChangeFile({...entry,scope:event.target.value as PendingReference['scope'],itemIds:event.target.value==='shared'?[]:entry.itemIds})}><option value="shared">共同参考资料</option><option value="items">指定项目参考资料</option></select>:null}{entry.scope==='items'?<div className="designer-reference-item-options">{items.map((item)=><label key={item.id}><input type="checkbox" checked={entry.itemIds.includes(item.id)} onChange={(event)=>onChangeFile({...entry,itemIds:event.target.checked?[...entry.itemIds,item.id]:entry.itemIds.filter((id)=>id!==item.id)})}/>{item.item_name||item.item_type}</label>)}</div>:null}</span><button type="button" aria-label={`移除 ${entry.file.name}`} onClick={()=>onRemove(entry)}><Trash2 size={16}/></button></div>):null}{attachments.map((file)=>{const image=file.content_type.startsWith('image/');const pdf=file.content_type==='application/pdf';return <div className="designer-reference-row" key={file.id}>{image&&urls[file.storage_path]?<button type="button" className="designer-reference-thumbnail" aria-label={`放大预览 ${file.original_name}`} onClick={()=>void open(file.storage_path)}><img src={urls[file.storage_path]} alt=""/></button>:<FileText size={20}/>}<span><b>{file.original_name}</b><small>{formatFileSize(file.size_bytes)} · {file.reference_scope==='items'?'指定项目参考资料':'共同参考资料'} · 已上传</small></span><button type="button" className={pdf?'designer-reference-pdf-preview':''} aria-label={`预览 ${file.original_name}`} title={pdf?'预览 PDF':'预览图片'} onClick={()=>void open(file.storage_path)}><Eye size={16}/>{pdf?<em>预览 PDF</em>:null}</button><button type="button" aria-label={`下载 ${file.original_name}`} title="下载" onClick={()=>void open(file.storage_path)}><Download size={16}/></button>{onDeleteAttachment?<button type="button" disabled={removingAttachmentId===file.id} aria-label={`移除 ${file.original_name}`} onClick={()=>onDeleteAttachment(file)}><Trash2 size={16}/></button>:null}</div>})}</div>
    {!readonly?<Field label="备注说明"><textarea placeholder="如不同项目参考要求不同，请在此说明，并与美工组确认" value={note} onChange={(event)=>onNote(event.target.value)} /></Field>:null}
  </div>
}
function ReferenceFileVisual({file}:{file:File}){const [url,setUrl]=useState('');useEffect(()=>{if(!file.type.startsWith('image/'))return;const next=URL.createObjectURL(file);setUrl(next);return()=>URL.revokeObjectURL(next);},[file]);return url?<button type="button" className="designer-reference-thumbnail" aria-label={`放大预览 ${file.name}`} onClick={()=>window.open(url,'_blank','noopener,noreferrer')}><img src={url} alt=""/></button>:<FileText size={20}/>}

function RequestDetail({ request, stage, intake = false, applicant = false, onClose, onReview, onStageAction }: { request: DesignerRequestV2; stage?: DesignerStage; intake?: boolean; applicant?: boolean; onClose: () => void; onReview?: (stage: DesignerStage, accepted: boolean) => Promise<void>; onStageAction?: (stage: DesignerStage, action: StageAction) => Promise<void> }) {
  const active = stage ?? request.stages.find((item) => item.status === 'awaiting_agent_confirmation') ?? request.stages[0];
  const action = nextAction(active?.status, intake); const setup = request.work_mode === 'setup_only';
  const [removedAttachmentIds,setRemovedAttachmentIds]=useState<string[]>([]); const [cleanupPaths,setCleanupPaths]=useState<Record<string,string>>({}); const [removingAttachmentId,setRemovingAttachmentId]=useState(''); const [referenceError,setReferenceError]=useState('');
  const itemViews = request.request_items.length ? request.request_items : [{ id: 'legacy', item_type: request.request_type, item_name: null, sort_order: 0 }];
  const [selectedItemId, setSelectedItemId] = useState(itemViews[0]?.id ?? 'legacy');
  const [historyOpen, setHistoryOpen] = useState(false);
  const selectedItem = itemViews.find((item) => item.id === selectedItemId) ?? itemViews[0];
  const attachments=request.reference_attachments.filter((file)=>!removedAttachmentIds.includes(file.id));
  const sharedAttachments = attachments.filter((file) => file.reference_scope === 'shared');
  const selectedAttachments = selectedItem?.id === 'legacy' ? [] : attachments.filter((file) => file.reference_scope === 'items' && file.request_item_ids.includes(selectedItem.id));
  const allowRemove=canRemoveDesignerReference(request.status,applicant);
  async function removeAttachment(file:DesignerReferenceAttachment){
    if(!window.confirm(`确定移除“${file.original_name}”吗？此操作会删除参考资料文件。`))return;
    setReferenceError('');setRemovingAttachmentId(file.id);
    try{if(cleanupPaths[file.id])await designerRequestService.retryReferenceStorageCleanup(cleanupPaths[file.id]);else await designerRequestService.deleteReference(file.id);setRemovedAttachmentIds((ids)=>[...ids,file.id]);}
    catch(reason){if(reason instanceof ReferenceStorageCleanupError)setCleanupPaths((paths)=>({...paths,[file.id]:reason.storagePath}));setReferenceError(`移除失败：${errorMessage(reason)}。文件可能仍在安全存储中，请重试移除操作；若持续失败，请联系管理员。`);}
    finally{setRemovingAttachmentId('');}
  }
  const reviewStages = request.stages.filter((item) => item.status === 'awaiting_agent_confirmation');
  const footer = <><button className="designer-request-secondary" type="button" onClick={onClose}>关闭</button>{applicant && onReview ? reviewStages.map((item) => <span className="designer-detail-footer-actions" key={item.id}><button className="designer-request-secondary" type="button" onClick={() => void onReview(item, false)}>反馈问题</button><button className="designer-request-primary" type="button" onClick={() => void onReview(item, true)}>确认完成</button></span>) : null}{!applicant && active && action && onStageAction ? <button className="designer-request-primary" type="button" onClick={() => void onStageAction(active, action)}>{actionLabel(action)}</button> : null}</>;
  return <SystemModal title="美工申请详情" subtitle={`申请编号 · ${request.id}`} className="designer-request-modal designer-detail-modal designer-workspace-modal" onClose={onClose} footer={footer}>
    <section className="designer-workspace-summary"><div className="designer-workspace-identity"><b>{request.creator_name || '-'}</b><span>TikTok ID：{request.platform_user_id || '-'}</span><span>区域：{request.region?.name || '未分配'}</span></div><div className="designer-workspace-summary-rows"><span><small>活动日期与时间</small><DateRangeInline start={request.event_start_at} end={request.event_end_at} />{invalidEventRange(request.event_start_at, request.event_end_at) ? <em>结束时间早于开始时间</em> : null}</span><span><small>申请人</small><b>{displayEmployee(request.applicant, '未分配')}</b></span><span><small>申请日期</small><DateInline value={request.created_at} /></span><span><small>直播间</small><b>{request.live_room || '-'}</b></span></div><div className="designer-workspace-countdown"><small>活动剩余时间</small><strong>{remainingDays(request.event_start_at)}</strong><StatusBadge value={request.status === 'cancelled' ? '已取消' : request.stages.map(displayStageStatus).join(' / ') || '处理中'} /></div></section>
    <section className="designer-workspace-projects"><h4>申请项目 <small>({itemViews.length})</small></h4><div>{itemViews.map((item, index) => <button type="button" key={item.id} className={selectedItem?.id === item.id ? 'is-selected' : ''} onClick={() => setSelectedItemId(item.id)}><i>{index + 1}</i><span><b>{item.item_name || itemLabel(item.item_type, request)}</b><small>{workModeLabel(request.work_mode)} · 负责人：{displayEmployee(request.stages.find((stage) => stage.assignee)?.assignee ?? null, '未分配')}</small></span><StatusBadge value={itemStatusLabel(item, request, setup)} /></button>)}</div></section>
    <div className="designer-workspace-layout"><main className="designer-workspace-main"><header><div><span>项目详情</span><h3>{selectedItem?.item_name || itemLabel(selectedItem?.item_type || request.request_type, request)}</h3></div><StatusBadge value={itemStatusLabel(selectedItem, request, setup)} /></header><div className="designer-workspace-progress">{request.stages.length ? request.stages.map((item) => <article key={item.id} className={`stage-${item.stage_type} is-${item.status}`}><i /><b>{stageNames[item.stage_type]}</b><small>{displayStageStatus(item)}</small></article>) : <div className="designer-detail-empty">暂无阶段记录</div>}</div><div className="designer-workspace-content-grid"><section className="designer-workspace-requirements"><h4>设计要求</h4><dl className="designer-detail-requirements"><DetailField label="项目类型" value={setup ? '活动布置' : itemLabel(selectedItem?.item_type || request.request_type, request)} /><DetailField label="工作方式" value={workModeLabel(request.work_mode)} /><DetailField label="尺寸 / 规格" value={request.specification} /><DetailField label="内容" value={request.design_content} /><DetailField label="主题 / 风格" value={request.style} /><DetailField label="颜色" value={request.color} /><DetailField label="备注" value={request.special_content} /></dl>{request.reference_note ? <section className="designer-detail-note"><b>共同备注</b><p>{request.reference_note}</p></section> : null}</section><section className="designer-workspace-references"><h4>参考资料</h4>{designerReferenceUploadsEnabled ? <ReferenceGallery attachments={[...sharedAttachments, ...selectedAttachments]} legacyUrls={request.reference_urls} onDelete={allowRemove ? removeAttachment : undefined} removingAttachmentId={removingAttachmentId} /> : <div className="designer-detail-empty">暂无参考资料</div>}{referenceError ? <p className="designer-request-read-error">{referenceError}</p> : null}</section></div><section className="designer-workspace-results"><h4>{setup ? '现场完成照片' : '设计成果'}</h4><ReferenceGallery attachments={[]} legacyUrls={request.design_urls} emptyText={setup ? '暂无现场完成照片' : '暂无设计成果'} /></section><section className="designer-workspace-history"><button type="button" aria-expanded={historyOpen} onClick={() => setHistoryOpen((open) => !open)}><span>处理记录</span><span>{historyOpen ? '收起' : '展开'}⌄</span></button>{historyOpen ? <div className="designer-detail-timeline"><TimelineEntry title="申请提交" time={request.created_at} />{request.stages.flatMap((item) => [item.accepted_at ? <TimelineEntry key={`${item.id}-accepted`} title={`${stageNames[item.stage_type]}接单`} time={item.accepted_at} tone="pending" /> : null, item.submitted_at ? <TimelineEntry key={`${item.id}-submitted`} title={`${stageNames[item.stage_type]}提交`} time={item.submitted_at} tone="active" /> : null, item.confirmed_at ? <TimelineEntry key={`${item.id}-confirmed`} title={`${stageNames[item.stage_type]}确认 / 完成`} time={item.confirmed_at} tone="completed" /> : null, item.feedback ? <TimelineEntry key={`${item.id}-feedback`} title="退回修改" detail={item.feedback} tone="revision" /> : null])}</div> : null}</section></main><aside className="designer-workspace-sidebar"><section><h4>当前状态</h4><StatusBadge value={itemStatusLabel(selectedItem, request, setup)} /><dl><dt>当前阶段</dt><dd>{active ? stageNames[active.stage_type] : '-'}</dd><dt>负责人</dt><dd>{displayEmployee(request.stages.find((stage) => stage.assignee)?.assignee ?? null, '未分配')}</dd></dl></section>{itemViews.length > 1 ? <section><h4>相关项目</h4>{itemViews.map((item) => <button type="button" key={item.id} className={selectedItem?.id === item.id ? 'is-selected' : ''} onClick={() => setSelectedItemId(item.id)}>{item.item_name || itemLabel(item.item_type, request)}<span>›</span></button>)}</section> : null}</aside></div>
  </SystemModal>;
}

function DetailField({ label, value }: { label: string; value: string | null | undefined }) { return value ? <><dt>{label}</dt><dd>{value}</dd></> : null; }
function DateInline({ value }: { value: string | null }) { return <b className="designer-workspace-date-inline">{formatMalaysiaDateTime(value)}</b>; }
function DateRangeInline({ start, end }: { start: string | null; end: string | null }) { return <b className="designer-workspace-date-inline">{formatMalaysiaRange(start, end)}</b>; }
function TimelineEntry({ title, time, detail, tone = 'submitted' }: { title: string; time?: string | null; detail?: string; tone?: 'submitted'|'pending'|'active'|'completed'|'revision' }) { return <article className={`is-${tone}`}><i /><div><b>{title}</b>{time ? <small>{formatMalaysiaDateTime(time)}</small> : null}{detail ? <p>{detail}</p> : null}</div></article>; }
function itemLabel(type: string, request: DesignerRequestV2) { if (type === 'setup') return '活动布置'; if (type === 'special') return request.other_design_type || '其他设计'; return designTypeNames[type as DesignType] || type || displayDesignType(request); }
function itemStatusLabel(_item: { item_type: string } | undefined, request: DesignerRequestV2, setup: boolean) { const matching = request.stages.find((stage) => setup ? stage.stage_type === 'setup' : stage.stage_type === 'design') ?? request.stages[0]; return matching ? displayStageStatus(matching) : request.status === 'cancelled' ? '已取消' : '待处理'; }
function remainingDays(value: string | null) { if (!value) return '-'; const diff = Math.ceil((new Date(value).getTime() - Date.now()) / 86400000); return diff < 0 ? `已过期 ${Math.abs(diff)} 天` : diff === 0 ? '今天' : `剩余 ${diff} 天`; }
function invalidEventRange(start: string | null, end: string | null) { return Boolean(start && end && new Date(end).getTime() < new Date(start).getTime()); }
function formatMalaysiaDateTime(value: string | null | undefined) { return value ? new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Kuala_Lumpur', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(value)).replaceAll('/', '-') : '-'; }
function formatMalaysiaRange(start: string | null, end: string | null) { return start || end ? `${formatMalaysiaDateTime(start)}${end ? ` → ${formatMalaysiaDateTime(end)}` : ''}` : '-'; }

function CancelModal({ onClose, onConfirm }: { onClose: () => void; onConfirm: () => Promise<void> }) { return <SystemModal title="取消申请" wide={false} className="designer-request-modal designer-request-confirm-modal" onClose={onClose} footer={<><button className="designer-request-secondary" type="button" onClick={onClose}>返回</button><button className="designer-request-danger" type="button" onClick={() => void onConfirm()}>确认取消</button></>}><p>确定取消这份美工申请吗？</p><p>取消后将保留记录，但不能继续接单或处理。</p></SystemModal>; }

function nextAction(status: StageStatus | undefined, intake: boolean): StageAction | null { if (intake) return 'claim'; if (status === 'scheduled') return 'arrange'; if (status === 'arranged') return 'start'; return status === 'in_progress' || status === 'revision' ? 'submit' : null; }
function actionLabel(action: StageAction | null) { return action === 'claim' ? '接单' : action === 'arrange' ? '确认安排' : action === 'start' ? '开始布置' : action === 'submit' ? '提交完成确认' : '暂无可执行操作'; }
function StatusBadge({ value }: { value: string }) { const kind = value === '已取消' ? 'cancelled' : value.includes('完成') ? 'done' : value.includes('进行') ? 'active' : 'pending'; return <span className={`designer-request-badge designer-request-badge-${kind}`}>{value}</span>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="designer-request-field"><span>{label}</span>{children}</label>; }
function TextField({ label, value, onChange, required = false }: { label: string; value: string; onChange: (value: string) => void; required?: boolean }) { return <Field label={label}><input required={required} value={value} onChange={(event) => onChange(event.target.value)} /></Field>; }
function displayTaskType(taskType: TaskType | null): string { return taskType ? taskTypeNames[taskType] : '-'; }
function displayDesignType(request: DesignerRequestV2): string { if (request.work_mode === 'setup_only') return '-'; return request.request_type === 'special' ? request.other_design_type || '-' : designTypeNames[request.request_type]; }
function workModeLabel(workMode: WorkMode | null): string { return workMode === 'design_production' ? '设计 + 制作' : workMode === 'setup_only' ? '布置' : '纯设计'; }
function dateInput(value: string | null): string { return value ? value.slice(0, 16) : ''; }
function formatDate(value: string | null): string { return value ? value.replace('T', ' ').slice(0, 16) : '-'; }
function displayEmployee(employee: { full_name: string | null; nickname: string | null } | null, fallback: string) { return employee?.nickname || employee?.full_name || fallback; }
const malaysiaDateFormatter = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kuala_Lumpur', year: 'numeric', month: '2-digit', day: '2-digit' });
function malaysiaDateKey(value: string | null) { if (!value) return ''; const parts = malaysiaDateFormatter.formatToParts(new Date(value)); const fields = Object.fromEntries(parts.filter((part) => part.type !== 'literal').map((part) => [part.type, part.value])); return `${fields.year}-${fields.month}-${fields.day}`; }
function malaysiaTodayKey() { return malaysiaDateKey(new Date().toISOString()); }
function calendarDayNumber(dateKey: string) { const [year, month, day] = dateKey.split('-').map(Number); return Math.floor(Date.UTC(year, month - 1, day) / 86400000); }
function matchesKeyword(request: DesignerRequestV2, keyword: string) { const query = keyword.trim().toLowerCase(); return !query || [request.creator_name, request.platform_user_id, request.platform_account].some((value) => value?.toLowerCase().includes(query)); }
function agentBucket(request: DesignerRequestV2): Exclude<AgentStatusFilter, 'all'> { if (request.status === 'completed') return 'completed'; if (request.status === 'cancelled') return 'cancelled'; if (request.stages.some((stage) => stage.status === 'awaiting_agent_confirmation')) return 'awaiting'; return 'processing'; }
function sortAgentRequests(first: DesignerRequestV2, second: DesignerRequestV2) { const rank: Record<Exclude<AgentStatusFilter, 'all'>, number> = { awaiting: 0, processing: 1, completed: 2, cancelled: 3 }; return rank[agentBucket(first)] - rank[agentBucket(second)] || new Date(second.created_at).getTime() - new Date(first.created_at).getTime(); }
function matchesIntake(request: WorkflowItem, filters: IntakeFilters, workstream: DesignerWorkstream) { return matchesKeyword(request, filters.keyword) && (!filters.taskType || request.task_type === filters.taskType) && (workstream === 'setup' || !filters.designType || request.request_type === filters.designType) && (!filters.applicant || displayEmployee(request.applicant, '') === filters.applicant) && (!filters.eventDate || malaysiaDateKey(request.event_start_at) === filters.eventDate) && (!filters.submittedDate || malaysiaDateKey(request.created_at) === filters.submittedDate) && (!filters.region || request.region?.name === filters.region); }
function matchesProgress(request: WorkflowItem, filters: ProgressFilters) { const stage = request.stage; if (!stage) return false; return (!filters.activeOnly || stage.status === 'in_progress' || stage.status === 'revision') && (!filters.owner || displayEmployee(stage.assignee, '').toLowerCase().includes(filters.owner.trim().toLowerCase())) && (!filters.stageType || stage.stage_type === filters.stageType) && (!filters.status || stage.status === filters.status) && matchesKeyword(request, filters.keyword) && (!filters.applicant || displayEmployee(request.applicant, '') === filters.applicant) && (!filters.eventDate || malaysiaDateKey(request.event_start_at) === filters.eventDate); }
function compareEventDate(first: DesignerRequestV2, second: DesignerRequestV2) { const firstDate = first.event_start_at ? calendarDayNumber(malaysiaDateKey(first.event_start_at)) : Number.MAX_SAFE_INTEGER; const secondDate = second.event_start_at ? calendarDayNumber(malaysiaDateKey(second.event_start_at)) : Number.MAX_SAFE_INTEGER; return firstDate - secondDate; }
function sortIntakeRequests(first: WorkflowItem, second: WorkflowItem, workstream: DesignerWorkstream) { return workstream === 'setup' ? compareEventDate(first, second) || new Date(first.created_at).getTime() - new Date(second.created_at).getTime() : new Date(first.created_at).getTime() - new Date(second.created_at).getTime(); }
function sortProgressRequests(first: WorkflowItem, second: WorkflowItem) { const rank = (item: WorkflowItem) => item.stage?.status === 'in_progress' || item.stage?.status === 'revision' ? 0 : item.stage?.status === 'scheduled' || item.stage?.status === 'arranged' ? 1 : 2; return rank(first) - rank(second) || compareEventDate(first, second) || new Date(second.stage?.accepted_at ?? 0).getTime() - new Date(first.stage?.accepted_at ?? 0).getTime(); }
function requestRisk(request: WorkflowItem) { if (!request.event_start_at || request.status === 'completed' || request.status === 'cancelled' || request.stage?.status === 'completed') return ''; const days = calendarDayNumber(malaysiaDateKey(request.event_start_at)) - calendarDayNumber(malaysiaTodayKey()); if (days < 0) return '已过活动日期'; if (request.work_mode === 'setup_only' && days < 10) return '时间较紧'; if (request.work_mode === 'design_production' && days < 15) return '制作周期紧张'; return ''; }
function formatFileSize(size:number){return size>=1024*1024?`${(size/(1024*1024)).toFixed(1)} MB`:`${Math.max(1,Math.round(size/1024))} KB`;}
type DesignerRequestRpcError = { code?: unknown; message?: unknown; details?: unknown; hint?: unknown };

function errorMessage(reason: unknown): string {
  if (reason instanceof Error) return reason.message;

  if (reason && typeof reason === 'object') {
    const error = reason as DesignerRequestRpcError;
    const message = typeof error.message === 'string' && error.message.trim() ? error.message : '';

    if (import.meta.env.DEV) {
      console.error('Designer request operation failed', {
        code: typeof error.code === 'string' ? error.code : undefined,
        message: message || undefined,
        details: typeof error.details === 'string' ? error.details : undefined,
        hint: typeof error.hint === 'string' ? error.hint : undefined,
      });
    }

    if (message) return message;
  }

  return typeof reason === 'string' && reason.trim() ? reason : '操作失败';
}
